store("inspect",`(r)=>{const t=r.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");const rows=[...t.matchAll(/^\\s*([1-9])\\s+([XO.](?:\\s+[XO.]){8})\\s+\\1\\s*$/gm)];if(rows.length!==9)return {text:t};const b={};const cs="ABCDEFGHJ";for(const m of rows)m[2].trim().split(/\\s+/).forEach((v,i)=>b[cs[i]+m[1]]=v);const adj=p=>{let x=cs.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([x,y])=>x>=0&&x<9&&y>0&&y<10).map(([x,y])=>cs[x]+y)};let seen=new Set(),groups=[],regions=[];for(const p in b){if(seen.has(p))continue;let v=b[p],stack=[p],pts=[],border=new Set(),libs=new Set();seen.add(p);while(stack.length){let q=stack.pop();pts.push(q);for(const a of adj(q)){if(b[a]===v&&!seen.has(a)){seen.add(a);stack.push(a)}else if(b[a]!==v){border.add(b[a]);if(b[a]===".")libs.add(a)}}}if(v===".")regions.push({points:pts.sort(),borders:[...border]});else groups.push({color:v,stones:pts.sort(),liberties:[...libs].sort()})}return {board:b,groups,regions}}`);
